(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const wx = w1x + Math.sin((y+w1y)*0.025-t*0.5)*8;
  const wy = w1y + Math.cos((x+w1x)*0.02+t*0.4)*8;
  const sx = x+wx, sy = y+wy;
  const w2x = Math.sin(sy*0.03+t*0.7)*5 + Math.cos(sx*0.025-t*0.6)*4;
  const w2y = Math.cos(sx*0.028-t*0.5)*5 + Math.sin(sy*0.022+t*0.8)*4;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 1.0],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+4)*60, 200+Math.sin(t*0.75+1)*40, 0.085, 1.8, 1.15]
  ];
  let aS=0, iS=0, hS=0;
  for (const [sX,sY,f,sp,amp] of src) {
    const d = Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS += Math.sin(d*f-t*sp)*amp;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    hS += Math.sin(d*f*0.5-t*sp*0.4+3.0)*amp*0.5;
  }
  const n=src.length, act=aS/n, inh=iS/n, het=hS/n;
  let bg = Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1)*0.8
    +Math.sin((fx+fy)*0.12+t*2.5)*0.3+Math.sin((fx-fy)*0.1-t*2)*0.3
    +Math.sin(fx*0.08+fy*0.06-t*1.5)*0.4+Math.sin(fx*0.15-fy*0.12+t*3)*0.15;
  bg /= 2.95;
  const dist = Math.sqrt((fx-cx)**2+(fy-cy)**2);
  const ang = Math.atan2(fy-cy, fx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)
    +Math.sin(dist*0.07-ang*2+t*0.8)*0.5)*0.35;
  const rd1 = Math.tanh((act-inh*0.7+bg*0.3+spiral+het*0.4)*2.2);
  const fine = Math.sin(fx*0.2)*Math.sin(fy*0.2)+Math.sin((fx+fy)*0.15+t*1.5)*0.5
    +Math.sin(fx*0.3-fy*0.25+t*2.5)*0.25;
  const cell = Math.tanh(fine*1.5)*0.3;
  const gx = Math.cos(fx*0.2)*0.2*Math.sin(fy*0.2)+Math.cos((fx+fy)*0.15+t*1.5)*0.075;
  const gy = Math.sin(fx*0.2)*Math.cos(fy*0.2)*0.2+Math.cos((fx+fy)*0.15+t*1.5)*0.075;
  const edge = Math.min(1, Math.sqrt(gx*gx+gy*gy)*4);
  const blend = rd1*0.6+cell*0.2+edge*0.2, v = blend*0.5+0.5;
  const pal = [[5,10,45],[12,50,95],[18,100,120],[25,155,130],[120,185,90],
    [210,190,60],[230,140,55],[215,85,65],[180,50,80],[120,30,70],[70,20,65],[30,15,55],[5,10,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0, pal.length-2), f=idx-i, sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(rd1*Math.PI)*0.15;
  const hi=Math.max(0,rd1-0.5)*0.6, sh=Math.max(0,-rd1-0.3)*0.3;
  return [
    Math.min(255,Math.max(0,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum+hi*80-sh*30)|0)),
    Math.min(255,Math.max(0,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum+hi*60-sh*20)|0)),
    Math.min(255,Math.max(0,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum+hi*40-sh*10)|0))
  ];
}
